//! Generates the compile-time tables of embedded reference data (ADR 0013).
//!
//! Four roots under `data/` are embedded: `fixtures`, `spells`, `party` and
//! `baseline`. A missing root embeds as an empty table, so the baseline can be
//! generated by a binary built before it exists.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};
use std::{env, fs};

fn collect(root: &Path, dir: &Path, out: &mut Vec<(String, PathBuf)>) {
    let Ok(read) = fs::read_dir(dir) else { return };
    let mut paths: Vec<PathBuf> = read.filter_map(Result::ok).map(|e| e.path()).collect();
    paths.sort();
    for path in paths {
        if path.is_dir() {
            collect(root, &path, out);
        } else if path.extension().is_some_and(|x| x == "json") {
            let rel = path.strip_prefix(root).expect("path under root").to_string_lossy().replace('\\', "/");
            out.push((rel, path));
        }
    }
}

fn main() {
    let manifest = PathBuf::from(env::var("CARGO_MANIFEST_DIR").expect("cargo sets the manifest dir"));
    let data = manifest.parent().expect("workspace root").join("data");
    let mut code = String::new();
    for (name, dir) in [("FIXTURES", "fixtures"), ("SPELLS", "spells"), ("PARTY", "party"), ("BASELINE", "baseline")] {
        let root = data.join(dir);
        println!("cargo:rerun-if-changed={}", root.display());
        let mut files = Vec::new();
        collect(&root, &root, &mut files);
        files.sort_by(|a, b| a.0.cmp(&b.0));
        assert!(name == "BASELINE" || !files.is_empty(), "data/{dir} holds no json files to embed");
        if name == "SPELLS" {
            assert!(files.iter().any(|f| f.0 == "effects.json"), "data/spells/effects.json is missing");
        }
        if name == "PARTY" {
            assert!(files.iter().any(|f| f.0.starts_with("standard/")), "data/party/standard holds no party members");
        }
        writeln!(code, "pub static {name}: &[(&str, &str)] = &[").unwrap();
        for (rel, abs) in files {
            writeln!(code, "    ({rel:?}, include_str!({:?})),", abs.to_string_lossy()).unwrap();
        }
        code.push_str("];\n");
    }
    let out = PathBuf::from(env::var("OUT_DIR").expect("cargo sets OUT_DIR")).join("embedded_data.rs");
    fs::write(out, code).expect("write embedded table");
}
